/**
 * Verify every Bí Kíp lesson against the real engine:
 *  - start positions are well-formed (25 chars, legal symbols);
 *  - every step's move is generated by the engine at that point (so
 *    Luật Mở forced-gánh and all movement rules hold);
 *  - claimed flip counts (gánh + chẹt) actually happen;
 *  - turns alternate correctly from startTurn.
 * Run: npx tsx scripts/verify-lessons.ts
 */
import { ALL_LESSONS } from "../lib/coganh/lessons";
import {
  boardFromString, boardToString, legalMoves, applyMove, moveLabel,
  type Color, type Move,
} from "../lib/coganh/engine";
import { parseCgLabel } from "../lib/coganh/replay";

let failed = 0;
const ok = (cond: boolean, msg: string) => {
  if (!cond) { console.log("FAIL:", msg); failed++; }
};

for (const lesson of ALL_LESSONS) {
  ok(/^cg-/.test(lesson.id), `${lesson.id}: id prefix`);
  ok(lesson.startPos.length === 25, `${lesson.id}: startPos length ${lesson.startPos.length}`);
  ok(/^[BR.]+$/.test(lesson.startPos), `${lesson.id}: startPos symbols`);
  let board = boardFromString(lesson.startPos);
  ok(boardToString(board) === lesson.startPos, `${lesson.id}: startPos round-trips`);
  let turn: Color = lesson.startTurn;
  lesson.steps.forEach((step, i) => {
    const parsed = parseCgLabel(step.move);
    ok(!!parsed, `${lesson.id} step ${i}: label parses (${step.move})`);
    if (!parsed) return;
    const moves = legalMoves(board, turn);
    const m: Move | undefined = moves.find(
      (x) => x.from === parsed.from && x.to === parsed.to
    );
    ok(!!m, `${lesson.id} step ${i}: ${step.move} legal for ${turn} (legal: ${moves.map((x) => moveLabel(x, applyMove(board, x, turn))).join(" ")})`);
    if (!m) return;
    const applied = applyMove(board, m, turn);
    const flips = applied.ganhFlips.length + applied.chetFlips.length;
    if (step.expectFlips !== undefined) {
      ok(flips === step.expectFlips,
        `${lesson.id} step ${i}: flips ${flips} != expected ${step.expectFlips}`);
    }
    board = applied.board;
    turn = turn === "blue" ? "red" : "blue";
  });
  console.log(`${lesson.id}: ${lesson.steps.length} steps checked`);
}
console.log(`\nlessons: ${ALL_LESSONS.length} lessons, ${failed} failures`);
process.exit(failed ? 1 : 0);
